CREATE TABLE rm_corporate_record_events (
 id INTEGER PRIMARY KEY,
 record_id TEXT NOT NULL CHECK(length(record_id) BETWEEN 3 AND 64),
 event_type TEXT NOT NULL CHECK(event_type IN ('ingested','enriched','linked','superseded')),
 record_type TEXT NOT NULL CHECK(record_type IN ('articles','registration','board_resolution','ownership_register','share_transfer','authority_letter','bank_mandate','tax_registration','other')),
 payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
 canonical_payload TEXT NOT NULL CHECK(length(canonical_payload) BETWEEN 2 AND 65536),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 created_at TEXT NOT NULL,
 UNIQUE(record_id,event_type,payload_hash)
);
CREATE TABLE rm_corporate_record_bytes (record_id TEXT PRIMARY KEY, original_bytes BLOB NOT NULL, sha256 TEXT NOT NULL UNIQUE CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'), filename TEXT NOT NULL, source TEXT NOT NULL, received_at TEXT NOT NULL, record_date TEXT, retention_until TEXT, uploader TEXT NOT NULL, sensitivity TEXT NOT NULL CHECK(sensitivity IN ('normal','confidential','restricted')));
CREATE TABLE rm_corporate_record_links (record_id TEXT NOT NULL, link_type TEXT NOT NULL CHECK(link_type IN ('company','party','ownership','disposition','legacy_evidence_ref')), link_id TEXT NOT NULL, PRIMARY KEY(record_id,link_type,link_id));
CREATE TRIGGER rm_corporate_record_events_no_update BEFORE UPDATE ON rm_corporate_record_events BEGIN SELECT RAISE(ABORT, 'corporate record events are append-only'); END;
CREATE TRIGGER rm_corporate_record_events_no_delete BEFORE DELETE ON rm_corporate_record_events BEGIN SELECT RAISE(ABORT, 'corporate record events are append-only'); END;
CREATE TRIGGER rm_corporate_record_bytes_no_update BEFORE UPDATE ON rm_corporate_record_bytes BEGIN SELECT RAISE(ABORT, 'corporate record bytes are immutable'); END;
CREATE TRIGGER rm_corporate_record_bytes_no_delete BEFORE DELETE ON rm_corporate_record_bytes BEGIN SELECT RAISE(ABORT, 'corporate record bytes are immutable'); END;
